-- Coffee Brewing Calculator — Phase 3 Feature #3 seed (Decision #67).
-- GENERATED by scripts/gen-catalog-seed.mjs from data/roasteries/*.json — do not edit by hand.
-- Idempotent: re-running refreshes each row. Per §13.2 a scraped row REPLACES a matching
-- (case-insensitive brand+name) user row — ON CONFLICT sets source='scraped'.
-- 191 single coffees (bundles/samplers/instant/drip-kits excluded). Run after 0003_coffee_repository_enrichment.sql.

on conflict (lower(brand), lower(coffee_name)) do update set
  roastery = excluded.roastery,
  origin_country = excluded.origin_country,
  origin_region = excluded.origin_region,
  origin_estate = excluded.origin_estate,
  altitude = excluded.altitude,
  variety = excluded.variety,
  process = excluded.process,
  roast_level = excluded.roast_level,
  tasting_notes = excluded.tasting_notes,
  variants = excluded.variants,
  availability = excluded.availability,
  source_url = excluded.source_url,
  last_amount_g = excluded.last_amount_g,
  source = 'scraped',
  updated_at = now();
